"import { NextResponse } from 'next/server'
import prisma from '@/lib/db'

export async function POST(request: Request) {
  try {
    const { meetingId } = await request.json()

    if (!meetingId) {
      return NextResponse.json({ error: 'Missing meetingId' }, { status: 400 })
    }

    // Mark meeting as recorded. Since transcripts and summaries are already provisioned 
    // by the `provisionDemoWorkspace` step when the user was created, we just need to 
    // update the meeting status so it appears in the Recent Recordings list.
    await prisma.meeting.update({
      where: { id: meetingId },
      data: { status: 'recorded' }
    })

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('Simulation error:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
"

